import heapq
from collections import defaultdict

def shortest_path(edges, start, end):
    # 負の重みのチェック（全てのエッジ）
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Weight cannot be negative")

    # グラフを邻接リストに変換
    graph = defaultdict(list)
    nodes = set()
    for u, v, w in edges:
        graph[u].append((v, w))
        nodes.add(u)
        nodes.add(v)

    if start == end:
        return (0, [start])

    # 初期化：各ノードまでの距離を無限大、親ノードの記録は未定義
    distances = {node: float('inf') for node in nodes}
    parent = {}
    distances[start] = 0

    # プライオリティキュー：(距離, ノード)
    pq = [(0, start)]

    visited = set()

    while pq:
        dist, node = heapq.heappop(pq)

        if node in visited:
            continue
        visited.add(node)

        if node == end:
            break

        for neighbor, weight in graph[node]:
            new_dist = dist + weight
            if new_dist < distances[neighbor] and neighbor not in visited:
                distances[neighbor] = new_dist
                parent[neighbor] = node
                heapq.heappush(pq, (new_dist, neighbor))

    # 最短経路の確認
    if distances[end] == float('inf') or end not in parent:
        return (None, None)

    # 経路の復元
    path = []
    current = end
    while current != start and current is not None:
        path.append(current)
        current = parent.get(current)
    path.append(start)
    path.reverse()

    return (distances[end], path)
